def label(name, role):
    return f"{name}: {role}"

print(label("Mira", "Scout"))

def dispatch_status(party, supplies, warning_active):
    if warning_active or len(party) == 0:
        return "Denied"
    elif len(supplies) >= len(party) * 2:
        return "Ready"
    else:
        return "Review"
